// Everything under /api and every page needs a signed-in user except the
// Clerk auth pages themselves — this is a single-tenant-per-user notes app,
// there's no public read path.
const isPublicRoute = createRouteMatcher(["/sign-in(.*)", "/sign-up(.*)"]);

