import { existsSync } from "node:fs";
import { defineConfig, devices } from "@playwright/test";

// Playwright runs as a bare script — load the app's own .env.local so the
// Clerk keys (+ OPENROUTER_API_KEY for the chat spec) are available.
if (existsSync(".env.local")) {
  process.loadEnvFile(".env.local");
}

const PORT = 3000;
const baseURL = `http://localhost:${PORT}`;

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: process.env.CI ? "github" : "list",
  timeout: 45_000,
  use: {
    baseURL,
    trace: "on-first-retry",
  },
  projects: [
    { name: "setup", testMatch: /auth\.setup\.ts/ },
    {
      name: "signed-out",
      testMatch: /\.signed-out\.spec\.ts/,
      use: { ...devices["Desktop Chrome"] },
    },
    {
      name: "chromium",
      testIgnore: /\.signed-out\.spec\.ts/,
      dependencies: ["setup"],
      use: {
        ...devices["Desktop Chrome"],
        storageState: "e2e/.clerk/user.json",
      },
    },
  ],
  // Reuse the dev server if one is already up (that's the common local case);
  // otherwise start it.
  webServer: {
    command: "bun run dev",
    url: baseURL,
    reuseExistingServer: true,
    timeout: 120_000,
    cwd: "../..",
  },
});

import { clerk, clerkSetup } from "@clerk/testing/playwright";
import { test as setup } from "@playwright/test";

const authFile = "e2e/.clerk/user.json";

/**
 * Signs in via Clerk's ticket flow (no password / OAuth needed — the backend
 * mints a one-time sign-in token for an existing user) and saves the session
 * to `authFile` for the `chromium` project.
 *
 * Requires:
 *   CLERK_SECRET_KEY, NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY  (from .env.local)
 *   E2E_CLERK_USER_EMAIL  — the email of an existing Clerk user to sign in as
 *
 * Without E2E_CLERK_USER_EMAIL the signed-in specs are skipped, not failed.
 */
setup("authenticate", async ({ page }) => {
  const email = process.env.E2E_CLERK_USER_EMAIL;
  setup.skip(
    !email || !process.env.CLERK_SECRET_KEY,
    "set E2E_CLERK_USER_EMAIL (and CLERK_SECRET_KEY) to run the signed-in E2E specs"
  );

  await clerkSetup();
  await page.goto("/sign-in");
  await clerk.signIn({ page, emailAddress: email as string });
  await page.goto("/notes");
  await page.waitForURL("**/notes");
  await page.context().storageState({ path: authFile });
});

